fn get_triple(a: &[i64]) -> usize {
    if a.len() < 3 {
        return a.len();
    }
    for i in 0..a.len() - 2 {
        if a[i] == a[i + 1] && a[i] == a[i + 2] {
            return i;
        }
    }
    a.len()
}

